import tseslint from "typescript-eslint"
import { jsdocConvention } from "../../eslint.jsdoc.js"

export default tseslint.config({ ignores: ["dist/**"] }, {
  files: ["src/**/*.ts"],
  languageOptions: { parser: tseslint.parser }
}, ...jsdocConvention)

{
  "name": "@smthrs/rpc",
  "version": "0.0.0",
  "private": true,
  "smthrs": {
    "group": "tooling"
  },
  "type": "module",
  "description": "Contract modules shared by the Smithers app (apps/mvp), the terminal app (apps/tui), the model host and the site: zod schemas, route constants, and RPC types, plus BrowserFetch, the browser-tool fetch handler",
  "exports": {
    "./package.json": "./package.json",
    ".": {
      "types": "./src/index.ts",
      "default": "./src/index.ts"
    },
    "./*": {
      "types": "./src/*.ts",
      "default": "./src/*.ts"
    },
    "./fixtures/*": {
      "types": "./test/fixtures/*.ts",
      "default": "./test/fixtures/*.ts"
    },
    "./testing/LiveDocRelay": {
      "types": "./src/testing/LiveDocRelay.ts",
      "default": "./src/testing/LiveDocRelay.ts"
    }
  },
  "scripts": {
    "check": "vibelang -b tsconfig.json && vibelang -p tsconfig.test.json --noEmit",
    "typecheck": "vibelang --noEmit",
    "test": "vitest run",
    "lint": "eslint src --max-warnings=0 && dprint check"
  },
  "dependencies": {
    "@smthrs/canonical": "1.0.0-rc.16",
    "string-width": "7.2.0",
    "zod": "4.6.7",
    "yjs": "13.6.32"
  },
  "devDependencies": {
    "@types/node": "26.4.1",
    "dprint": "0.55.2",
    "eslint": "9.39.1",
    "typescript": "^5.9.3",
    "typescript-eslint": "8.65.0",
    "vibelang": "0.0.8",
    "vibelang-vite": "0.0.8",
    "vitest": "5.0.0"
  }
}

import vibelang from "vibelang-vite"
import { defineConfig } from "vitest/config"

export default defineConfig({
  plugins: [vibelang({ project: "tsconfig.test.json" })],
  test: { include: ["test/**/*.test.{ts,vibe}"], environment: "node", testTimeout: 30_000 }
})
